SELECT COUNT(*) FROM im_messages
WHERE session_id = #{sessionId}
  AND sender_id = #{senderId}
  AND receiver_id = #{receiverId}
  AND created_at > (
      SELECT COALESCE(MAX(created_at), '1970-01-01')
      FROM im_messages
      WHERE session_id = #{sessionId}
        AND sender_id = #{receiverId}
        AND receiver_id = #{senderId}
  )

